1	package strategy
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"log/slog"
9		"os"
10		"os/exec"
11		"sync"
12		"time"
13	
14		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
15		"github.com/entireio/cli/cmd/entire/cli/logging"
16		"github.com/entireio/cli/cmd/entire/cli/paths"
17	
18		"github.com/go-git/go-git/v6"
19		"github.com/go-git/go-git/v6/plumbing"
20		"github.com/go-git/go-git/v6/plumbing/object"
21	)
22	
23	// disconnectedOnce ensures the disconnection warning runs at most once per process.
24	var disconnectedOnce sync.Once //nolint:gochecknoglobals // intentional per-process gate
25	
26	// IsMetadataDisconnected checks whether local and remote entire/checkpoints/v1
27	// branches exist but share no common ancestor (the "empty-orphan bug").
28	// Returns (false, nil) if either branch is missing, they point to the same hash,
29	// or they share a common ancestor (normal divergence handled by push merge).
30	// Returns (true, nil) only when both exist and are truly disconnected.
31	func IsMetadataDisconnected(ctx context.Context, repo *git.Repository) (bool, error) {
32		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
33		localRef, err := repo.Reference(refName, true)
34		if errors.Is(err, plumbing.ErrReferenceNotFound) {
35			return false, nil
36		}
37		if err != nil {
38			return false, fmt.Errorf("failed to check local metadata branch: %w", err)
39		}
40	
41		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
42		remoteRef, err := repo.Reference(remoteRefName, true)
43		if errors.Is(err, plumbing.ErrReferenceNotFound) {
44			return false, nil
45		}
46		if err != nil {
47			return false, fmt.Errorf("failed to check remote metadata branch: %w", err)
48		}
49	
50		if localRef.Hash() == remoteRef.Hash() {
51			return false, nil
52		}
53	
54		repoPath, err := getRepoPath(repo)
55		if err != nil {
56			return false, err
57		}
58	
59		return isDisconnected(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
60	}
61	
62	// WarnIfMetadataDisconnected checks (once per process) whether the metadata
63	// branch is disconnected and prints a warning to stderr if so.
64	// It does NOT fix the problem — users are directed to 'entire doctor'.
65	//
66	// Uses sync.Once, so a transient failure on the first call permanently suppresses
67	// the warning. This is acceptable because the check is advisory only and
68	// 'entire doctor' is the authoritative repair path.
69	func WarnIfMetadataDisconnected() {
70		disconnectedOnce.Do(func() {
71			ctx := context.Background()
72			repo, err := OpenRepository(ctx)
73			if err != nil {
74				logging.Debug(ctx, "metadata disconnection check: could not open repository",
75					slog.String("error", err.Error()))
76				return
77			}
78			disconnected, err := IsMetadataDisconnected(ctx, repo)
79			if err != nil {
80				logging.Debug(ctx, "metadata disconnection check failed",
81					slog.String("error", err.Error()))
82				return
83			}
84			if !disconnected {
85				return
86			}
87			fmt.Fprintln(os.Stderr, "[entire] Warning: Local and remote session metadata branches are disconnected.")
88			fmt.Fprintln(os.Stderr, "[entire] Some checkpoints from remote may not be visible. Run 'entire doctor' to fix.")
89		})
90	}
91	
92	// ReconcileDisconnectedMetadataBranch detects and repairs disconnected local/remote
93	// entire/checkpoints/v1 branches. Disconnected means no common ancestor, which
94	// only happens due to the empty-orphan bug. Diverged (shared ancestor) is normal
95	// and handled by the push path's tree merge.
96	//
97	// Repair strategy: cherry-pick local commits onto remote tip, preserving all data.
98	// Checkpoint shards use unique paths (<id[:2]>/<id[2:]>/), so cherry-picks always
99	// apply cleanly.
100	//
101	// Progress messages are written to w (typically os.Stderr for hooks or
102	// cmd.ErrOrStderr() for commands).
103	func ReconcileDisconnectedMetadataBranch(ctx context.Context, repo *git.Repository, w io.Writer) error {
104		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
105	
106		// Check local branch
107		localRef, err := repo.Reference(refName, true)
108		if errors.Is(err, plumbing.ErrReferenceNotFound) {
109			return nil // No local branch — nothing to reconcile
110		}
111		if err != nil {
112			return fmt.Errorf("failed to check local metadata branch: %w", err)
113		}
114	
115		// Check remote-tracking branch
116		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
117		remoteRef, err := repo.Reference(remoteRefName, true)
118		if errors.Is(err, plumbing.ErrReferenceNotFound) {
119			return nil // No remote branch — nothing to reconcile
120		}
121		if err != nil {
122			return fmt.Errorf("failed to check remote metadata branch: %w", err)
123		}
124	
125		localHash := localRef.Hash()
126		remoteHash := remoteRef.Hash()
127	
128		// Same hash — nothing to do
129		if localHash == remoteHash {
130			return nil
131		}
132	
133		// Check if disconnected using git merge-base
134		repoPath, err := getRepoPath(repo)
135		if err != nil {
136			return err
137		}
138	
139		disconnected, err := isDisconnected(ctx, repoPath, localHash.String(), remoteHash.String())
140		if err != nil {
141			return fmt.Errorf("failed to check metadata branch ancestry: %w", err)
142		}
143		if !disconnected {
144			// Shared ancestry (diverged or ancestor) — not our problem
145			return nil
146		}
147	
148		// Disconnected — cherry-pick local commits onto remote tip
149		fmt.Fprintln(w, "[entire] Detected disconnected session metadata (local and remote share no common ancestor)")
150	
151		// Collect local commits oldest-first
152		localCommits, err := collectCommitChain(repo, localHash)
153		if err != nil {
154			return fmt.Errorf("failed to collect local commits: %w", err)
155		}
156	
157		// Filter out empty-tree commits (the orphan bug commit)
158		var dataCommits []*object.Commit
159		for _, c := range localCommits {
160			tree, treeErr := c.Tree()
161			if treeErr != nil {
162				return fmt.Errorf("failed to read tree for commit %s: %w", c.Hash.String()[:7], treeErr)
163			}
164			if len(tree.Entries) > 0 {
165				dataCommits = append(dataCommits, c)
166			}
167		}
168	
169		if len(dataCommits) == 0 {
170			// Local only had empty orphan — just point to remote
171			ref := plumbing.NewHashReference(refName, remoteHash)
172			if err := repo.Storer.SetReference(ref); err != nil {
173				return fmt.Errorf("failed to reset metadata branch to remote: %w", err)
174			}
175			fmt.Fprintln(w, "[entire] Done — local had no checkpoint data, reset to remote")
176			return nil
177		}
178	
179		fmt.Fprintf(w, "[entire] Cherry-picking %d local checkpoint(s) onto remote...\n", len(dataCommits))
180	
181		newTip, err := cherryPickOnto(repo, remoteHash, dataCommits)
182		if err != nil {
183			return fmt.Errorf("failed to cherry-pick local commits onto remote: %w", err)
184		}
185	
186		// Update local branch ref
187		ref := plumbing.NewHashReference(refName, newTip)
188		if err := repo.Storer.SetReference(ref); err != nil {
189			return fmt.Errorf("failed to update metadata branch: %w", err)
190		}
191	
192		fmt.Fprintln(w, "[entire] Done — all local and remote checkpoints preserved")
193		return nil
194	}
195	
196	// isDisconnected checks if two commits have no common ancestor using git merge-base.
197	// Returns (true, nil) if disconnected, (false, nil) if they share ancestry,
198	// or (false, error) if git merge-base failed for another reason.
199	//
200	// git merge-base exit codes:
201	//   - 0: common ancestor found (shared ancestry)
202	//   - 1: no common ancestor (disconnected)
203	//   - 128+: error (corrupt repo, invalid hash, etc.)
204	func isDisconnected(ctx context.Context, repoPath, hashA, hashB string) (bool, error) {
205		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
206		defer cancel()
207		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
208		cmd.Dir = repoPath
209		if err := cmd.Run(); err != nil {
210			var exitErr *exec.ExitError
211			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
212				return true, nil // No common ancestor — disconnected
213			}
214			return false, fmt.Errorf("git merge-base failed: %w", err)
215		}
216		return false, nil // Shared ancestry
217	}
218	
219	// collectCommitChain walks from tip to root following first parent, returns oldest-first.
220	func collectCommitChain(repo *git.Repository, tip plumbing.Hash) ([]*object.Commit, error) {
221		var chain []*object.Commit
222		current := tip
223	
224		reachedRoot := false
225		for range MaxCommitTraversalDepth {
226			commit, err := repo.CommitObject(current)
227			if err != nil {
228				return nil, fmt.Errorf("failed to get commit %s: %w", current, err)
229			}
230			chain = append(chain, commit)
231	
232			if len(commit.ParentHashes) == 0 {
233				reachedRoot = true
234				break
235			}
236			current = commit.ParentHashes[0]
237		}
238	
239		if !reachedRoot {
240			return nil, fmt.Errorf("commit chain exceeded %d commits without reaching root; aborting reconciliation", MaxCommitTraversalDepth)
241		}
242	
243		// Reverse to oldest-first
244		for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
245			chain[i], chain[j] = chain[j], chain[i]
246		}
247	
248		return chain, nil
249	}
250	
251	// cherryPickOnto applies each commit's delta onto base, building a linear chain.
252	// For each commit, it computes the full diff from its parent (additions, modifications,
253	// and deletions), then applies that delta onto the current tip's tree.
254	func cherryPickOnto(repo *git.Repository, base plumbing.Hash, commits []*object.Commit) (plumbing.Hash, error) {
255		currentTip := base
256	
257		for _, commit := range commits {
258			// Get the commit's tree entries
259			commitTree, err := commit.Tree()
260			if err != nil {
261				return plumbing.ZeroHash, fmt.Errorf("failed to get tree for commit %s: %w", commit.Hash, err)
262			}
263	
264			commitEntries := make(map[string]object.TreeEntry)
265			if err := checkpoint.FlattenTree(repo, commitTree, "", commitEntries); err != nil {
266				return plumbing.ZeroHash, fmt.Errorf("failed to flatten commit tree: %w", err)
267			}
268	
269			// Get parent's tree entries (empty if root commit)
270			parentEntries := make(map[string]object.TreeEntry)
271			if len(commit.ParentHashes) > 0 {
272				parentCommit, pErr := repo.CommitObject(commit.ParentHashes[0])
273				if pErr != nil {
274					return plumbing.ZeroHash, fmt.Errorf("failed to get parent commit %s: %w", commit.ParentHashes[0], pErr)
275				}
276				parentTree, ptErr := parentCommit.Tree()
277				if ptErr != nil {
278					return plumbing.ZeroHash, fmt.Errorf("failed to get parent tree for commit %s: %w", commit.ParentHashes[0], ptErr)
279				}
280				if err := checkpoint.FlattenTree(repo, parentTree, "", parentEntries); err != nil {
281					return plumbing.ZeroHash, fmt.Errorf("failed to flatten parent tree for commit %s: %w", commit.ParentHashes[0], err)
282				}
283			}
284	
285			// Compute full delta: additions, modifications, and deletions
286			added := make(map[string]object.TreeEntry)
287			for path, entry := range commitEntries {
288				parentEntry, exists := parentEntries[path]
289				if !exists || parentEntry.Hash != entry.Hash {
290					added[path] = entry // New or modified
291				}
292			}
293			var deleted []string
294			for path := range parentEntries {
295				if _, exists := commitEntries[path]; !exists {
296					deleted = append(deleted, path) // Removed in this commit
297				}
298			}
299	
300			if len(added) == 0 && len(deleted) == 0 {
301				continue // Skip no-op commits
302			}
303	
304			// Get current tip's tree and apply delta
305			tipCommit, err := repo.CommitObject(currentTip)
306			if err != nil {
307				return plumbing.ZeroHash, fmt.Errorf("failed to get tip commit: %w", err)
308			}
309			tipTree, err := tipCommit.Tree()
310			if err != nil {
311				return plumbing.ZeroHash, fmt.Errorf("failed to get tip tree: %w", err)
312			}
313	
314			mergedEntries := make(map[string]object.TreeEntry)
315			if err := checkpoint.FlattenTree(repo, tipTree, "", mergedEntries); err != nil {
316				return plumbing.ZeroHash, fmt.Errorf("failed to flatten tip tree: %w", err)
317			}
318			for path, entry := range added {
319				mergedEntries[path] = entry
320			}
321			for _, path := range deleted {
322				delete(mergedEntries, path)
323			}
324	
325			mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, mergedEntries)
326			if err != nil {
327				return plumbing.ZeroHash, fmt.Errorf("failed to build merged tree: %w", err)
328			}
329	
330			// Create new commit on top of current tip, preserving original message/author
