26	// pushRefIfNeeded pushes a custom ref to the given target if it exists locally.
27	// Custom refs (under refs/entire/) don't have remote-tracking refs, so there's
28	// no "has unpushed" optimization — we always attempt the push and let git handle
29	// the no-op case.
30	func pushRefIfNeeded(ctx context.Context, target string, refName plumbing.ReferenceName) error {
