197	// detectRemoteOnlyArchives discovers archived generation refs on the remote
198	// that don't exist locally. Returns them sorted ascending (oldest first).
199	func detectRemoteOnlyArchives(ctx context.Context, target string, repo *git.Repository) ([]string, error) {
200		ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
201		defer cancel()
202	
203		cmd := CheckpointGitCommand(ctx, target, "ls-remote", target, paths.V2FullRefPrefix+"*")
204		cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
205		output, err := cmd.Output()
206		if err != nil {
207			return nil, fmt.Errorf("ls-remote failed: %w", err)
208		}
209	
210		var remoteOnly []string
211		for _, line := range strings.Split(strings.TrimSpace(string(output)), "\n") {
212			if line == "" {
213				continue
214			}
215			parts := strings.Fields(line)
216			if len(parts) < 2 {
217				continue
218			}
219			refName := parts[1]
220			suffix := strings.TrimPrefix(refName, paths.V2FullRefPrefix)
221			if suffix == "current" || !checkpoint.GenerationRefPattern.MatchString(suffix) {
222				continue
223			}
