225			// could be stale if another machine updated it via rotation conflict recovery,
226			// but that's unlikely and the checkpoints are still on /main regardless.
227			if _, err := repo.Reference(plumbing.ReferenceName(refName), true); err != nil {
228				remoteOnly = append(remoteOnly, suffix)
229			}
230		}
231	
232		sort.Strings(remoteOnly)
233		return remoteOnly, nil
234	}
