377		newBlobHash, err := checkpoint.CreateBlobFromContent(repo, updatedData)
378		if err != nil {
379			return object.TreeEntry{}, fmt.Errorf("failed to create generation blob: %w", err)
380		}
381	
382		return object.TreeEntry{
383			Name: paths.GenerationFileName,
384			Mode: filemode.Regular,
385			Hash: newBlobHash,
386		}, nil
387	}
388	
389	// pushV2Refs pushes v2 checkpoint refs to the target.
390	// Pushes /main, /full/current, and the latest archived generation (if any).
391	// Older archived generations are immutable and were pushed when created.
392	func pushV2Refs(ctx context.Context, target string) {
